import numpy as np

# load relaxed cod
lines = open("cod_fixed.xyz").read().splitlines()
n = int(lines[0]); codE=[]; codP=[]
for ln in lines[2:2+n]:
    p=ln.split(); codE.append(p[0]); codP.append([float(x) for x in p[1:4]])
codP = np.array(codP)

alpha = np.radians(125); sa, ca = np.sin(alpha), np.cos(alpha)
def leg(beta_deg, dist):
    b = np.radians(beta_deg)
    return dist*np.array([sa*np.cos(b), sa*np.sin(b), ca])

Ru = np.zeros(3)
r_ring=1.208; z_cp=1.85; cc_me=1.50; ch=1.09
ringC=[]; meC=[]
for i in range(5):
    th=np.radians(90+72*i)
    u_out=np.array([np.cos(th),np.sin(th),0.0])
    ringC.append(r_ring*u_out+np.array([0,0,z_cp])); meC.append((r_ring+cc_me)*u_out+np.array([0,0,z_cp]))
Cl = leg(90, 2.42)

def methyl_Hs(i, off):
    th=np.radians(90+72*i)
    u_in=-np.array([np.cos(th),np.sin(th),0.0]); t_hat=np.array([-np.sin(th),np.cos(th),0.0]); z_hat=np.array([0.,0.,1.])
    Hs=[]
    for phi in (off, off+120, off+240):
        p=np.cos(np.radians(phi))*t_hat+np.sin(np.radians(phi))*z_hat
        d=(-1/3)*u_in+(2*np.sqrt(2)/3)*p; d/=np.linalg.norm(d)
        Hs.append(meC[i]+ch*d)
    return Hs
meH=[]
for i in range(5):
    best=None
    for off in range(0,120,5):
        Hs=methyl_Hs(i,off)
        mind=min(np.linalg.norm(Hp-cp) for Hp in Hs for cp in codP)
        if best is None or mind>best[0]: best=(mind,off,Hs)
    meH += best[2]
    print(f"methyl {i}: offset {best[1]}, min H-cod {round(best[0],3)}")

atoms=[("Ru",Ru)]
for rc in ringC: atoms.append(("C",rc))
for mc in meC: atoms.append(("C",mc))
for hp in meH: atoms.append(("H",hp))
atoms.append(("Cl",Cl))
for e,p in zip(codE,codP): atoms.append((e,p))

with open("guess5.xyz","w") as f:
    f.write(f"{len(atoms)}\nCp*Ru(cod)Cl v5\n")
    for el,p in atoms: f.write(f"{el:2s} {p[0]:12.6f} {p[1]:12.6f} {p[2]:12.6f}\n")
print("atoms:", len(atoms))

import itertools
C=np.array([p for _,p in atoms]); E=[e for e,_ in atoms]
# bonded pairs to exclude from clash check
bonds=set()
def addb(a,b): bonds.add((min(a,b),max(a,b)))
for i in range(1,6):
    addb(i, 1+(i%5)); addb(i, 5+i)
for i in range(6,11):
    for j in range(3): addb(i, 11+3*(i-6)+j)
addb(27,28); addb(28,29); addb(29,30); addb(30,31); addb(31,32); addb(32,33); addb(33,34); addb(34,27)
codH={27:[35],28:[36],29:[37,38],30:[39,40],31:[41],32:[42],33:[43,44],34:[45,46]}
for c,hhs in codH.items():
    for hh in hhs: addb(c,hh)
worst=[]
for i,j in itertools.combinations(range(len(E)),2):
    if (i,j) in bonds: continue
    dd=np.linalg.norm(C[i]-C[j])
    lim = 1.7 if (E[i]=="H" and E[j]=="H") else (2.2 if "H" in (E[i],E[j]) else 2.0)
    if dd<lim: worst.append((E[i],i,E[j],j,round(dd,3)))
worst.sort(key=lambda x:x[4])
print("nonbonded close contacts:", worst)
